 * @return 1 (poor) to 4 (excellent), or -1 if disconnected.
 */
int WifiStatusWidget::getRssiCategory() {
    if (WiFi.status() != WL_CONNECTED) return -1;
    int rssi = WiFi.RSSI();
    if (rssi < -85) return 1;
    if (rssi < -75) return 2;
    if (rssi < -65) return 3;
    return 4;
}

